//! Formal charges of the complete Chemical Component Dictionary, generated by
//! `tools/components/charges.py`.

use std::sync::OnceLock;

use crate::io::element_symbol::parse_structure_element_symbol;
use crate::molecule::Element;

const TABLE: &str = include_str!("../../../data/components/charges.tsv");
const RELEASE: &str = "# Release: entries modified up to ";

/// The formal charges the complete wwPDB Chemical Component Dictionary
/// states for one component with a charged atom or an atom whose charge it
/// states as unknown.
///
/// Readers charge residues of components without a template from it (see
/// [`StructureInterpretIssue::ChargesFromDictionary`](crate::macromolecular::StructureInterpretIssue::ChargesFromDictionary)).
/// Components whose atoms the dictionary states all neutral, and components
/// it lacks, have no entry.
///
/// ```
/// use kekule::components::DictionaryCharges;
///
/// let tris = DictionaryCharges::get("TRS").expect("charged");
/// let nitrogen = tris.atoms().find(|atom| atom.name() == "N").unwrap();
/// assert_eq!(nitrogen.formal_charge(), Some(1));
/// assert!(DictionaryCharges::get("GOL").is_none());
/// assert!(DictionaryCharges::release().starts_with("20"));
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DictionaryCharges {
    entry: &'static Entry,
}

/// One atom of a [`DictionaryCharges`] entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DictionaryAtomCharge {
    name: &'static str,
    element: Element,
    formal_charge: Option<i8>,
}

impl DictionaryAtomCharge {
    /// The atom name (`_chem_comp_atom.atom_id`).
    pub const fn name(self) -> &'static str {
        self.name
    }

    /// The element of the atom's type symbol.
    pub const fn element(self) -> Element {
        self.element
    }

    /// The formal charge in e, or `None` where the dictionary states it as
    /// unknown (`?`).
    pub const fn formal_charge(self) -> Option<i8> {
        self.formal_charge
    }
}

#[derive(Debug)]
struct Entry {
    id: &'static str,
    /// The row's atom fields, parsed on first use.
    row: &'static str,
    atoms: OnceLock<Box<[DictionaryAtomCharge]>>,
}

impl PartialEq for Entry {
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id
    }
}

impl Eq for Entry {}

struct Table {
    release: &'static str,
    entries: Vec<Entry>,
}

/// The table's identifiers, indexed on first use. It is compiled in and
/// checked by tests, so a row it cannot read is a defect.
fn table() -> &'static Table {
    static TABLE_ENTRIES: OnceLock<Table> = OnceLock::new();
    TABLE_ENTRIES.get_or_init(|| {
        let release = TABLE
            .lines()
            .find_map(|line| line.strip_prefix(RELEASE))
            .and_then(|rest| rest.strip_suffix('.'))
            .expect("the charge table states its release");
        let entries = TABLE
            .lines()
            .filter(|line| !line.starts_with('#'))
            .map(|line| {
                let (id, row) = line.split_once('\t').expect("charge table rows have atoms");
                Entry {
                    id,
                    row,
                    atoms: OnceLock::new(),
                }
            })
            .collect::<Vec<_>>();
        Table { release, entries }
    })
}

/// One atom field: its name, `/` and its element unless that is the name's
/// first letter, and `=` and its charge unless that is zero, or `=?`.
fn atom(field: &'static str) -> DictionaryAtomCharge {
    let (named, charge) = field.split_once('=').unwrap_or((field, "0"));
    let (name, symbol) = named.split_once('/').unwrap_or((named, &named[..1]));
    let (element, _) = parse_structure_element_symbol(symbol)
        .unwrap_or_else(|| panic!("charge table element {symbol:?} is an element"));
    let formal_charge = match charge {
        "?" => None,
        charge => Some(
            charge
                .parse()
                .unwrap_or_else(|_| panic!("charge table charge {charge:?} is a whole number")),
        ),
    };
    DictionaryAtomCharge {
        name,
        element,
        formal_charge,
    }
}

impl DictionaryCharges {
    /// The entry of a component, compared case-insensitively.
    pub fn get(component_id: &str) -> Option<Self> {
        let entries = &table().entries;
        let id = component_id.trim();
        entries
            .binary_search_by(|entry| {
                entry
                    .id
                    .bytes()
                    .cmp(id.bytes().map(|byte| byte.to_ascii_uppercase()))
            })
            .ok()
            .map(|index| Self {
                entry: &entries[index],
            })
    }

    /// Every entry, ordered by component identifier.
    pub fn all() -> impl ExactSizeIterator<Item = Self> {
        table().entries.iter().map(|entry| Self { entry })
    }

    /// The dictionary release the table comes from: the latest modification
    /// date of its entries, such as `2026-11-13`.
    pub fn release() -> &'static str {
        table().release
    }

    /// The component identifier, such as `TRS`.
    pub fn id(self) -> &'static str {
        self.entry.id
    }

    /// The component's atoms in dictionary order, except its uncharged
    /// hydrogens.
    pub fn atoms(self) -> impl ExactSizeIterator<Item = DictionaryAtomCharge> {
        let entry = self.entry;
        entry
            .atoms
            .get_or_init(|| entry.row.split('\t').map(atom).collect())
            .iter()
            .copied()
    }

    /// The atom of that name.
    pub fn atom(self, name: &str) -> Option<DictionaryAtomCharge> {
        self.atoms().find(|atom| atom.name == name)
    }
}
